// One independent dictionary per output pixel. Each batch is bounded by
// device limits and a scratch-memory budget. Input/output colors use u32 RGB.
const shader = `
struct Entry { key:u32, count:u32, first:u32, }
struct Settings { pixels:u32, frames:u32, capacity:u32, unused:u32, }
@group(0) @binding(0) var<storage,read> input:array<u32>;
@group(0) @binding(1) var<storage,read_write> table:array<Entry>;
@group(0) @binding(2) var<storage,read_write> output:array<u32>;
@group(0) @binding(3) var<uniform> settings:Settings;
fn hash_key(value:u32)->u32 {
 var h=value;h=(h^(h>>16u))*0x7feb352du;h=(h^(h>>15u))*0x846ca68bu;return h^(h>>16u);
}
@compute @workgroup_size(64) fn main(@builtin(global_invocation_id) id:vec3<u32>) {
 let p=id.x;if(p>=settings.pixels){return;}let base=p*settings.capacity;
 var best=0u;var bestCount=0u;var bestFirst=0xffffffffu;
 for(var i=0u;i<settings.frames;i++) {
  let key=input[i*settings.pixels+p];var slot=hash_key(key)&(settings.capacity-1u);
  loop {
   let j=base+slot;
   if(table[j].count==0u){table[j].key=key;table[j].first=i;break;}
   if(table[j].key==key){break;}slot=(slot+1u)&(settings.capacity-1u);
  }
  let j=base+slot;table[j].count++;
  if(table[j].count>bestCount||(table[j].count==bestCount&&table[j].first<bestFirst)) {
   best=key;bestCount=table[j].count;bestFirst=table[j].first;
  }
 }
 output[p]=best;
}`;

function checkAbort(signal) {
  if (signal?.aborted) throw new DOMException('Processing cancelled', 'AbortError');
}

export async function modeWebGPU(frames, pixels, { signal, onProgress, batchPixels } = {}) {
  if (!globalThis.navigator?.gpu) throw new Error('WebGPU is not available');
  if (frames.length > 0x7fffffff) throw new RangeError('Frame count exceeds GPU limits');
  const adapter = await navigator.gpu.requestAdapter({ powerPreference: 'high-performance' });
  checkAbort(signal);
  if (!adapter) throw new Error('No WebGPU adapter is available');
  const device = await adapter.requestDevice();
  try {
    const capacity = 2 ** Math.ceil(Math.log2(frames.length * 2));
    const limit = Math.min(device.limits.maxStorageBufferBindingSize, device.limits.maxBufferSize);
    const tableBudget = Math.min(limit, 32 * 1024 * 1024);
    const inputBudget = Math.min(limit, 64 * 1024 * 1024);
    const maxBatch = Math.min(4096, Math.floor(tableBudget / (capacity * 12)),
      Math.floor(inputBudget / (frames.length * 4)), device.limits.maxComputeWorkgroupsPerDimension * 64);
    if (maxBatch < 1 || capacity > 0x80000000) throw new RangeError('Frame count exceeds available GPU buffer limits');
    const batch = Math.min(batchPixels ?? maxBatch, maxBatch);
    const output = new Uint8ClampedArray(pixels * 4);
    const pipeline = await device.createComputePipelineAsync({
      layout: 'auto', compute: { module: device.createShaderModule({ code: shader }), entryPoint: 'main' },
    });
    for (let start = 0; start < pixels; start += batch) {
      checkAbort(signal);
      const n = Math.min(batch, pixels - start);
      const input = new Uint32Array(n * frames.length);
      for (let f = 0; f < frames.length; f++) {
        const frame = frames[f];
        for (let p = 0; p < n; p++) {
          const index = (start + p) * 4;
          input[f * n + p] = (frame[index] << 16) | (frame[index + 1] << 8) | frame[index + 2];
        }
      }
      const buffers = [];
      const buffer = (descriptor) => { const b = device.createBuffer(descriptor); buffers.push(b); return b; };
      try {
        device.pushErrorScope('validation');
        device.pushErrorScope('out-of-memory');
        const src = buffer({ size: input.byteLength, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_DST });
        const table = buffer({ size: n * capacity * 12, usage: GPUBufferUsage.STORAGE });
        const out = buffer({ size: n * 4, usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC });
        const read = buffer({ size: n * 4, usage: GPUBufferUsage.MAP_READ | GPUBufferUsage.COPY_DST });
        const settings = buffer({ size: 16, usage: GPUBufferUsage.UNIFORM | GPUBufferUsage.COPY_DST });
        device.queue.writeBuffer(src, 0, input);
        device.queue.writeBuffer(settings, 0, new Uint32Array([n, frames.length, capacity, 0]));
        const bind = device.createBindGroup({ layout: pipeline.getBindGroupLayout(0), entries: [
          { binding: 0, resource: { buffer: src } }, { binding: 1, resource: { buffer: table } },
          { binding: 2, resource: { buffer: out } }, { binding: 3, resource: { buffer: settings } },
        ] });
        const encoder = device.createCommandEncoder(), pass = encoder.beginComputePass();
        pass.setPipeline(pipeline); pass.setBindGroup(0, bind); pass.dispatchWorkgroups(Math.ceil(n / 64)); pass.end();
        encoder.copyBufferToBuffer(out, 0, read, 0, n * 4); device.queue.submit([encoder.finish()]);
        await read.mapAsync(GPUMapMode.READ);
        const colors = new Uint32Array(read.getMappedRange());
        for (let p = 0; p < n; p++) {
          const i = (start + p) * 4, color = colors[p];
          output[i] = color >>> 16; output[i + 1] = (color >>> 8) & 255;
          output[i + 2] = color & 255; output[i + 3] = 255;
        }
        read.unmap();
        const allocationError = await device.popErrorScope();
        const validationError = await device.popErrorScope();
        if (allocationError || validationError) throw new Error((allocationError || validationError).message);
      } finally { for (const b of buffers) b.destroy(); }
      checkAbort(signal);
      if (onProgress) onProgress({ processor: 'webgpu', completed: start + n, total: pixels });
    }
    return output;
  } finally { device.destroy(); }
}
